mapper.select:


    sm.del_flag = 0

        and wf.id in

            #{item}




        and sm.id = #{id}


        and sm.scene_code = #{sceneCode}


        and sm.title LIKE CONCAT('%',#{title},'%')


        and sm.region_id = #{regionId}


        and sm.region_name  LIKE CONCAT('%',#{regionName},'%')


        and sm.version_code = #{versionCode}


        and sm.limit_price_desc = #{limitPriceDesc}


        and sm.file_group_id = #{fileGroupId}


        and remark = #{remark}


        and sm.project_id = #{projectId}


        and sm.project_name LIKE CONCAT('%',#{projectName},'%')


        and sm.dept_id = #{deptId}


        and sm.create_user = #{createUser}


        and sm.create_user_name = #{createUserName}


        and sm.create_time = #{createTime}


        and sm.update_user = #{updateUser}


        and sm.update_user_name = #{updateUserName}


        and sm.update_time = #{updateTime}


        and sm.del_user = #{delUser}


        and sm.del_time = #{delTime}


        and sm.pt_var1 = #{ptVar1}


        and sm.pt_var2 = #{ptVar2}


        and sm.pt_var3 = #{ptVar3}


        and sm.pt_var4 = #{ptVar4}


        and sm.version = #{version}


        and sm.valid = #{valid}


${params.dataScope}
order by id desc
